import subprocess
import os
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

# Configuration
DNS_LOOKUP_BINARY = os.environ.get('DNS_LOOKUP_BINARY', '/usr/bin/dig')
ALLOWED_RECORD_TYPES = ['A', 'AAAA', 'MX', 'CNAME', 'TXT', 'NS', 'SOA']
MAX_DOMAIN_LENGTH = 253
DNS_TIMEOUT = os.environ.get('DNS_TIMEOUT', '5')
DNS_SERVER = os.environ.get('DNS_SERVER', '8.8.8.8')

def validate_record_type(rtype):
    """Validate DNS record type against allowlist."""
    return rtype.upper() in ALLOWED_RECORD_TYPES

def sanitize_domain(domain):
    """Basic domain validation - checks length and null bytes."""
    if not domain or len(domain) > MAX_DOMAIN_LENGTH:
        return None
    if '\x00' in domain:
        return None
    # Strip trailing dot for canonical form
    domain = domain.rstrip('.')
    # Reject empty after strip
    if not domain:
        return None
    return domain

@app.route('/api/dns/lookup', methods=['POST'])
def dns_lookup():
    """Perform DNS lookup for the given domain and record type."""
    data = request.get_json()
    if not data:
        abort(400, description="JSON body required")

    domain = data.get('domain', '')
    record_type = data.get('type', 'A')

    # Validate record type
    if not validate_record_type(record_type):
        abort(400, description=f"Invalid record type. Allowed: {ALLOWED_RECORD_TYPES}")

    # Sanitize domain
    domain = sanitize_domain(domain)
    if domain is None:
        abort(400, description="Invalid domain name")

    # Build command - using dig for DNS resolution
    # Note: domain is validated for length and null bytes above
    cmd = f"{DNS_LOOKUP_BINARY} @{DNS_SERVER} +time={DNS_TIMEOUT} +tries=1 +short {domain} {record_type.upper()}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            text=True,
            timeout=int(DNS_TIMEOUT) + 2
        )

        output = result.stdout.strip()
        error = result.stderr.strip()

        if result.returncode != 0:
            return jsonify({
                'domain': domain,
                'type': record_type.upper(),
                'status': 'error',
                'error': error or 'Lookup failed'
            }), 502

        # Parse results
        records = [line.strip() for line in output.split('\n') if line.strip()]

        return jsonify({
            'domain': domain,
            'type': record_type.upper(),
            'status': 'success',
            'records': records,
            'server': DNS_SERVER
        })

    except subprocess.TimeoutExpired:
        return jsonify({
            'domain': domain,
            'type': record_type.upper(),
            'status': 'timeout',
            'error': 'DNS lookup timed out'
        }), 504
    except Exception as e:
        return jsonify({
            'status': 'error',
            'error': 'Internal server error'
        }), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
